-- auth-ui agent: SQL for the next migration.
--
-- REQUIRED: new table auth_sessions (backend/src/db/schema/auth-sessions.ts, exported from
-- schema/index.ts). `drizzle-kit generate` after merging should produce the equivalent of
-- the statements below; this is what the code expects.
--
-- One row per signed-in browser/device. The refresh JWT carries the row id as `sid`;
-- token_hash is the SHA-256 hex of the current refresh token (rotated on every refresh).
-- The id is a UUID generated by the app (no DB default, so no pgcrypto/PG13 dependency).
CREATE TABLE IF NOT EXISTS "auth_sessions" (
	"id" uuid PRIMARY KEY NOT NULL,
	"user_id" integer NOT NULL,
	"token_hash" text NOT NULL,
	"remember_me" boolean DEFAULT false NOT NULL,
	"expires_at" timestamp NOT NULL,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"last_used_at" timestamp DEFAULT now() NOT NULL,
	"user_agent" text
);
